        schema,
        schema,
        &json!({"requests":[{}]}),
        0
    ));
    assert_eq!(
        automatic_input(&json!({"requests":[{"query":"hello","model":"auto"}]}), 0).unwrap(),
        json!({"requests":[{"query":"hello"}]})
